INSERT OR REPLACE INTO charts (slug, family, title, subtitle, provenance, updated_at)
VALUES ('intl-market-vs-disposable-poverty', 'intl', 'Market vs disposable poverty, US and OECD peers', 'Poverty rate at 50% of median disposable income, latest available year per country (OECD IDD; latest year 2025)', '{"bruenig_post_url": "https://peoplespolicyproject.org/2025/10/07/does-europe-use-market-incomes-to-achieve-equality/", "bruenig_post_title": "Does Europe Use Market Incomes to Achieve Equality?", "source_name": "OECD Income Distribution Database (DF_IDD)", "source_url": "https://sdmx.oecd.org/public/rest/v1/data/OECD.WISE.INE,DSD_WISE_IDD@DF_IDD/.A.PR_INC_DISP+PR_INC_MRKT._Z.PT_POP._T.METH2012.D_CUR.PL_50", "source_detail": "SDMX CSV, key dims documented in recipe", "recipe_md": "US vs peer-country poverty: OECD Income Distribution Database (DF_IDD)\nvia the SDMX REST API, measures PR_INC_MRKT (market income) and\nPR_INC_DISP (disposable income), total population, post-2012 income\ndefinition (METH2012 / D_CUR), poverty line = 50% of median disposable\nincome (PL_50). Latest available year per country.\n\nThis is the same market-vs-disposable frame Bruenig uses in \"Does Europe\nUse Market Incomes to Achieve Equality?\" (Oct 2025) and the welfare-state\nposts; OECD definitions differ from the CPS ASEC recipe used for the US\nseries (equivalized disposable household income, 50%-of-median line), so\ncross-family comparisons are indicative only.\n\nx values are ''ISO3:YYYY'' (country code : that country''s latest data year)\nbecause country coverage years differ.\n"}', '2026-09-26 18:23:06');

